body::before, body::after { pointer-events: none; position: fixed; inset: 0; content: ""; z-index: 0; }

body::before {
  inset: -20% -20% -20% -20%;
  background: linear-gradient(120deg, rgba(var(--cp-neon-rgb),0.08) 0%, rgba(var(--cp-accent-rgb),0.06) 35%, rgba(0,0,0,0) 60%);
  mix-blend-mode: screen;
  opacity: 0.42;
  transform: translate3d(-8%, -6%, 0) rotate(0.001deg);
  will-change: transform, opacity;
  animation: cp-ambient-move 20s linear infinite;
  filter: blur(0.5px);
}

@keyframes cp-ambient-move {
  0% { transform: translate3d(-8%, -6%, 0) rotate(0.001deg); }
  50% { transform: translate3d(7%, 6%, 0) rotate(0.001deg); }
  100% { transform: translate3d(-8%, -6%, 0) rotate(0.001deg); }
}

body::after {
