.app-container::before {
  content: "";
  position: fixed;
  left: 50%;
  top: 20%;
  width: 120vw;
  height: 80vh;
  transform: translateX(-50%) translateY(-10%);
  background: radial-gradient(600px 400px at 50% 30%, rgba(var(--cp-neon-rgb),0.06), rgba(var(--cp-accent-rgb),0.03) 30%, transparent 60%);
  mix-blend-mode: screen;
  pointer-events: none;
  opacity: 0.7;
  z-index: 0;
  will-change: transform, opacity;
  animation: cp-sheen-drift 18s linear infinite;
}

.app-container::after {
  content: "";
  position: fixed;
  inset: -6vmax;
  pointer-events: none;
  z-index: 3;
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;
  opacity: 0;
  mix-blend-mode: screen;
  filter: drop-shadow(0 0 24px rgba(var(--cp-accent-rgb),0.10));
  will-change: opacity, transform, background-image, background-size, background-position;
  animation: cp-svg-signal-cycle 86s linear infinite;
}

